const input = ($json.chatInput || "").toLowerCase().trim();

let response;

if (["hi", "hello", "hey"].includes(input)) {
  response = "Hello! How can I help you today?";

} else if (["how are you", "how are you?"].includes(input)) {
  response = "I'm fine, thank you! How are you?";

} else if (["what is your name", "what is your name?"].includes(input)) {
  response = "My name is SimpleBot.";

} else if (["help", "what can you do"].includes(input)) {
  response = "I can respond to greetings, answer simple questions, and handle exit commands.";

} else if (["bye", "exit", "quit"].includes(input)) {
  response = "Goodbye! Have a great day!";

} else {
  response = "Sorry, I don't understand that. Please try another message.";
}

return [
  {
    json: {
      response: response
    }
  }
];
